import { ChangeDetectionStrategy, ChangeDetectorRef, Component, Inject, OnInit, Renderer2 } from '@angular/core';
import { DOCUMENT } from '@angular/common';
import { Router } from '@angular/router';
import { finalize } from 'rxjs/operators';
import { operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
import { BroadcastingService, roundNumber, TaxesService } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import { MessageService } from '@honoregaming/ui';
import { Bank, PaymentMethodType } from 'projects/customer/hg-account/src/lib/models/provider.model';
import { BankWithdrawProvider } from 'projects/customer/hg-account/src/lib/models/withdraw-provider.model';
import { AccountService } from 'projects/customer/hg-account/src/lib/services/account.service';
import { PaymentAccount } from 'projects/customer/hg-core/src/lib/models/payment-account.model';
import { TransactionPopupService } from 'projects/customer/hg-core/src/lib/services/transaction-popup.service';
import {
  GenericTransactionResponse,
  PaymentProviderValidationType
} from '../../models/generic-transaction-response.model';
import { CustomerWithdrawalInformations } from '../../models/customer-withdrawal-informations.model';
import { WithdrawProviderBaseComponent } from '../../provider-base';

@Component({
  selector: 'hg-withdraw-provider',
  templateUrl: './withdraw-provider.component.html',
  styleUrls: ['./withdraw-provider.component.scss', '../../provider-base/provider-base.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class WithdrawProviderComponent extends WithdrawProviderBaseComponent implements OnInit, BankWithdrawProvider {
  customerPaymentAccounts!: (PaymentAccount & { kind: PaymentMethodType })[];

  bankAccount: string | null = null;
  bankVerificationNumber: string | null = null;
  saveBankAccount: boolean = false;
  isSelectedBank: boolean = false;
  isSelectedAccount: boolean = false;
  isValidBankAccount: boolean = false;
  isValidBankVerificationNumber: boolean = false;
  selectedBankOrAccount: ((Bank | PaymentAccount) & { kind: PaymentMethodType }) | null = null;
  bankAccountPattern?: RegExp;
  bankVerificationNumberPattern?: RegExp;

  constructor(
    protected readonly accountService: AccountService,
    protected readonly i18nService: I18nService,
    protected readonly renderer: Renderer2,
    protected readonly cdRef: ChangeDetectorRef,
    protected readonly bcService: BroadcastingService,
    protected readonly taxesService: TaxesService,
    protected readonly messageService: MessageService,
    protected readonly router: Router,
    protected readonly transactionPopupService: TransactionPopupService,
    @Inject(DOCUMENT) private readonly document: Document,
    @Inject(operatorConfigurationToken) protected readonly operatorConfiguration: OperatorConfiguration
  ) {
    super(
      taxesService,
      messageService,
      i18nService,
      operatorConfiguration,
      renderer,
      cdRef,
      bcService,
      router,
      transactionPopupService,
      accountService
    );
  }

  ngOnInit(): void {
    super.ngOnInit();

    this.providerUpper = this.provider.parentProviderName.toUpperCase();
    this.customerPaymentAccounts = this.customerPaymentAccounts.map(cpa => {
      return { ...cpa, kind: PaymentMethodType.Account };
    });
    this.provider.banks = this.provider.banks.map(bank => {
      return { ...bank, kind: PaymentMethodType.Bank };
    });
  }

  get canSubmit(): boolean {
    const bankAccountInvalid: boolean = this.isSelectedBank && !this.isValidBankAccount;
    const bankVerificationNumberInvalid: boolean =
      this.isSelectedBank && !this.isValidBankVerificationNumber && !!this.bankVerificationNumber?.length;

    return (
      this.isValid &&
      !this.loading &&
      !!this.selectedBankOrAccount &&
      !bankAccountInvalid &&
      !bankVerificationNumberInvalid
    );
  }

  checkBankAccountValidity(value: string): void {
    this.isValidBankAccount = !!this.bankAccountPattern && !!value && this.bankAccountPattern.test(value);
  }

  checkBankVerificationNumberValidity(value: string): void {
    this.isValidBankVerificationNumber =
      !!this.bankVerificationNumberPattern && !!value && this.bankVerificationNumberPattern.test(value);
  }

  changeBankOrAccount(value: (PaymentAccount | Bank) & { kind: PaymentMethodType }): void {
    this.selectedBankOrAccount = value;

    if (value.kind === PaymentMethodType.Bank) {
      this.isSelectedBank = true;
      this.isSelectedAccount = false;
      this.bankAccountPattern = new RegExp(this.selectedBankOrAccount['bankAccountPattern']);
      this.bankVerificationNumberPattern = this.selectedBankOrAccount['bankVerificationNumberPattern']
        ? new RegExp(this.selectedBankOrAccount['bankVerificationNumberPattern'])
        : null;
    } else if (value.kind === PaymentMethodType.Account) {
      this.isSelectedAccount = true;
      this.isSelectedBank = false;
      this.saveBankAccount = false;
      this.bankAccount = null;
      this.bankVerificationNumber = null;
      this.isValidBankAccount = false;
      this.isValidBankVerificationNumber = false;
    }
  }

  submitWithdraw(): void {
    if (this.loading) {
      return;
    }

    this.loading = true;
    this.failure = null;
    this.accountService
      .createWithdraw(
        this.provider,
        roundNumber(this.amount, this.numberOfDecimals),
        this.selectedInnerProvider,
        null,
        {
          account: this.bankAccount,
          bankVerificationNumber: this.bankVerificationNumber,
          accountExternalRef: (this.selectedBankOrAccount as PaymentAccount)?.accountExternalRef,
          savePaymentAccount: this.saveBankAccount,
          bankIdentifier:
            this.selectedBankOrAccount.kind == PaymentMethodType.Bank
              ? (this.selectedBankOrAccount as Bank).identifier
              : null
        } as CustomerWithdrawalInformations
      )
      .pipe(
        finalize(() => {
          this.loading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        (response: GenericTransactionResponse) => {
          if (PaymentProviderValidationType[response.validationType] === PaymentProviderValidationType.Redirection) {
            this.document.location.href = response.value;
          } else {
            this.step = PaymentProviderValidationType[response.validationType];
            this.submitted = true;
            this.bcService.broadcast('payment-provider-scroll-to-top');
            this.withdrawSuccess.emit();
          }
        },
        (error: unknown) => {
          this.handleWithdrawError(error);
        }
      );
  }
}
